import { MakeLogicType, actions, kea, listeners, path, reducers } from 'kea'

import { captureCanvasAction } from '../canvasAnalytics'
import type { CanvasPanelTab } from './canvasPanelTabs'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface canvasSidePanelLogicValues {
    collapsed: boolean
    generatingPanelDismissed: boolean
    tab: CanvasPanelTab
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface canvasSidePanelLogicActions {
    openTab: (
        tab: CanvasPanelTab,
        canvasId: string
    ) => {
        canvasId: string
        tab: CanvasPanelTab
    }
    selectTab: (
        tab: CanvasPanelTab,
        canvasId: string
    ) => {
        canvasId: string
        tab: CanvasPanelTab
    }
    setCollapsed: (
        collapsed: boolean,
        canvasId: string
    ) => {
        canvasId: string
        collapsed: boolean
    }
}

export type canvasSidePanelLogicType = MakeLogicType<canvasSidePanelLogicValues, canvasSidePanelLogicActions>

/**
 * The canvas side panel's view state. Whether it is collapsed is a per-user preference that
 * persists across canvases and reloads, like PostHog Desktop's canvas chat panel.
 */
export const canvasSidePanelLogic = kea<canvasSidePanelLogicType>([
    path(['products', 'canvas', 'frontend', 'sidePanel', 'canvasSidePanelLogic']),
    actions({
        setCollapsed: (collapsed: boolean, canvasId: string) => ({ collapsed, canvasId }),
        /** The viewer picked a tab. */
        selectTab: (tab: CanvasPanelTab, canvasId: string) => ({ tab, canvasId }),
        /** Something else asked for a tab, for example a comment anchor clicked in the canvas. */
        openTab: (tab: CanvasPanelTab, canvasId: string) => ({ tab, canvasId }),
    }),
    reducers({
        collapsed: [
            false,
            { persist: true },
            {
                setCollapsed: (_, { collapsed }) => collapsed,
                openTab: () => false,
            },
        ],
        // A generating canvas opens the panel whatever the preference, until the viewer hides it on this visit.
        generatingPanelDismissed: [
            false,
            {
                setCollapsed: (_, { collapsed }) => collapsed,
                openTab: () => false,
            },
        ],
        tab: [
            'chat' as CanvasPanelTab,
            {
                selectTab: (_, { tab }) => tab,
                openTab: (_, { tab }) => tab,
            },
        ],
    }),
    listeners(({ values }) => ({
        selectTab: ({ tab, canvasId }) => {
            captureCanvasAction('panel_tab_change', { dashboard_id: canvasId, surface: 'web_canvas_side_panel', tab })
        },
        setCollapsed: ({ collapsed, canvasId }) => {
            captureCanvasAction('panel_toggle', { dashboard_id: canvasId, open: !collapsed, tab: values.tab })
        },
    })),
])
